mapper.select:
/* SNS 제공자 계정의 연동 행 조회 : 해제한 행도 UK 에 걸리므로 USE_YN 을 거르지 않는다 */
SELECT SNS_ACNT_LINK_SN
     , MBR_SN
     , SNS_OFFR_CD
     , USE_YN
  FROM SNS_ACNT_LINK
 WHERE SNS_OFFR_CD = #{snsOffrCd}
   AND OFFR_ACNT_ID = #{offrAcntId}

mapper.update:
/* 해제한 SNS 연동 되살림 : 조회 뒤 다른 요청이 먼저 바꿨으면 0행 */
UPDATE SNS_ACNT_LINK
   SET MBR_SN = #{mbrSn}
     , USE_YN = 'Y'
 WHERE SNS_ACNT_LINK_SN = #{snsAcntLinkSn}
   AND USE_YN = 'N'

mapper.insert:
/* SNS 연동 등록 */
INSERT INTO SNS_ACNT_LINK (
       MBR_SN
     , SNS_OFFR_CD
     , OFFR_ACNT_ID
) VALUES (
       #{mbrSn}
     , #{snsOffrCd}
     , #{offrAcntId}
)

INSERT INTO MBR (
       MBR_STTS_CD
     , MBR_AUTHRT_CD
     , JOIN_PATH_CD
     , ACNT_EML_ENC
     , ACNT_EML_HMAC
     , MBL_TELNO_ENC
     , MBL_TELNO_HMAC
     , PSWD_HASH
     , MBR_NCNM
     , NCNM_STNG_CMPTN_YN
) VALUES (
       #{mbrSttsCd}
     , #{mbrAuthrtCd}
     , #{joinPathCd}
     , #{acntEmlEnc}
     , #{acntEmlHmac}
     , #{mblTelnoEnc}
     , #{mblTelnoHmac}
     , #{pswdHash}
     , #{mbrNcnm}
     , 'N'
)

INSERT INTO MBR_STTS_HSTRY (
       MBR_SN
     , BFR_STTS_CD
     , AFTR_STTS_CD
     , CHG_RSN
) VALUES (
       #{mbrSn}
     , #{bfrSttsCd}
     , #{aftrSttsCd}
     , #{chgRsn}
)

INSERT INTO MBR_STTS_HSTRY (
       MBR_SN
     , PRCS_MBR_SN
     , BFR_STTS_CD
     , AFTR_STTS_CD
     , CHG_RSN
) VALUES (
       #{mbrSn}
     , #{prcsMbrSn}
     , #{bfrSttsCd}
     , #{aftrSttsCd}
     , #{chgRsn}
)

mapper.update:
UPDATE MBR
   SET MBR_NCNM = #{mbrNcnm}
     , NCNM_STNG_CMPTN_YN = 'Y'
     , MDFR_ID = #{actorId}
     , MDFCN_DT = NOW()
 WHERE MBR_SN = #{mbrSn}

/* 비밀번호 해시 변경(재설정) */
UPDATE MBR
   SET PSWD_HASH = #{pswdHash}
     , MDFR_ID = #{actorId}
     , MDFCN_DT = NOW()
 WHERE MBR_SN = #{mbrSn}
   AND MBR_STTS_CD != #{withdrawnSttsCd}

/* 회원탈퇴 : 정상 회원만 탈퇴로, 탈퇴 시각이 30일 보관의 기준 */
UPDATE MBR
   SET MBR_STTS_CD = #{withdrawnSttsCd}
     , WHDWL_DT = NOW()
     , MDFR_ID = #{actorId}
     , MDFCN_DT = NOW()
 WHERE MBR_SN = #{mbrSn}
   AND MBR_STTS_CD = #{normalSttsCd}

/* 탈퇴 보관 회원 복구 : 보관 기간 안일 때만 정상으로 */
UPDATE MBR
   SET MBR_STTS_CD = #{normalSttsCd}
     , WHDWL_DT = NULL
     , MDFR_ID = #{actorId}
     , MDFCN_DT = NOW()
 WHERE MBR_SN = #{mbrSn}
   AND MBR_STTS_CD = #{withdrawnSttsCd}
   AND WHDWL_DT IS NOT NULL
   AND WHDWL_DT > DATE_SUB(NOW(), INTERVAL #{keepDayCnt} DAY)

/* 휴대전화번호 저장 : 번호가 없는 회원만 */
UPDATE MBR
   SET MBL_TELNO_ENC = #{mblTelnoEnc}
     , MBL_TELNO_HMAC = #{mblTelnoHmac}
     , MDFR_ID = #{actorId}
     , MDFCN_DT = NOW()
 WHERE MBR_SN = #{mbrSn}
   AND MBL_TELNO_HMAC IS NULL

/* 회원정보 수정 : 보낸 값만 바꾼다(휴대전화번호, 프로필 사진 교체·기본 이미지로) */
UPDATE MBR
   SET MDFR_ID = #{actorId}
     , MDFCN_DT = NOW()

     , MBL_TELNO_ENC = #{mblTelnoEnc}
     , MBL_TELNO_HMAC = #{mblTelnoHmac}


     , ATCH_FILE_SN = #{atchFileSn}


     , ATCH_FILE_SN = NULL

 WHERE MBR_SN = #{mbrSn}

/* 최근 로그인 일시 갱신 */
UPDATE MBR
   SET LAST_LGN_DT = NOW()
     , MDFR_ID = #{actorId}
     , MDFCN_DT = NOW()
 WHERE MBR_SN = #{mbrSn}

mapper.select:
/* 탈퇴 보관일수 경과 회원 번호 조회 */
SELECT MBR_SN
  FROM MBR
 WHERE MBR_STTS_CD = #{mbrSttsCd}
   AND WHDWL_DT IS NOT NULL
   AND WHDWL_DT < DATE_SUB(NOW(), INTERVAL #{keepDayCnt} DAY)

/* 파기 대상 회원 번호 조회 : 아직 파기하지 않은 회원만 */
SELECT MBR_SN
  FROM MBR
 WHERE MBR_STTS_CD = #{mbrSttsCd}
   AND WHDWL_DT IS NOT NULL
   AND WHDWL_DT < DATE_SUB(NOW(), INTERVAL #{keepDayCnt} DAY)
   AND ACNT_EML_HMAC NOT LIKE #{purgedHmacPattern}
 ORDER BY MBR_SN

mapper.update:
/* 회원 식별값 파기 : 조회 뒤 복구한 회원은 바뀌지 않는다 */
UPDATE MBR
   SET ACNT_EML_ENC = #{acntEmlEnc}
     , ACNT_EML_HMAC = #{acntEmlHmac}
     , MBL_TELNO_ENC = NULL
     , MBL_TELNO_HMAC = NULL
     , PSWD_HASH = NULL
     , ATCH_FILE_SN = NULL
     , MBR_NCNM = #{mbrNcnm}
     , MDFR_ID = #{actorId}
     , MDFCN_DT = NOW()
 WHERE MBR_SN = #{mbrSn}
   AND MBR_STTS_CD = #{mbrSttsCd}
   AND WHDWL_DT IS NOT NULL
   AND WHDWL_DT < DATE_SUB(NOW(), INTERVAL #{keepDayCnt} DAY)

mapper.delete:
/* 회원의 SNS 연동 전체 삭제 */
DELETE FROM SNS_ACNT_LINK
 WHERE MBR_SN = #{mbrSn}

mapper.select:
/* 관리자 회원 목록 조회 */
SELECT MBR_SN
     , MBR_NCNM
     , ACNT_EML_ENC
     , JOIN_PATH_CD
     , MBR_STTS_CD
     , MBR_AUTHRT_CD
     , REG_DT
     , LAST_LGN_DT
  FROM MBR


        AND ACNT_EML_HMAC = #{acntEmlHmac}


        AND MBR_NCNM LIKE CONCAT('%', #{mbrNcnm}, '%')


        AND MBR_STTS_CD = #{cond.status}


        AND JOIN_PATH_CD = #{cond.joinPath}


        AND MBR_AUTHRT_CD = #{cond.role}


        AND REG_DT >= #{cond.bgngYmd}


        AND REG_DT < DATE_ADD(#{cond.endYmd}, INTERVAL 1 DAY)


 ORDER BY REG_DT DESC
        , MBR_SN DESC

mapper.update:
/* 회원 정지 : 정상 회원만 */
UPDATE MBR
   SET MBR_STTS_CD = #{suspendedSttsCd}
     , SUSPN_END_DT = #{suspnEndDt}
     , MDFR_ID = #{actorId}
     , MDFCN_DT = NOW()
 WHERE MBR_SN = #{mbrSn}
   AND MBR_STTS_CD = #{normalSttsCd}

/* 회원 정지 해제 : 정지 회원만 */
UPDATE MBR
   SET MBR_STTS_CD = #{normalSttsCd}
     , SUSPN_END_DT = NULL
     , MDFR_ID = #{actorId}
     , MDFCN_DT = NOW()
 WHERE MBR_SN = #{mbrSn}
   AND MBR_STTS_CD = #{suspendedSttsCd}

   AND SUSPN_END_DT <= #{expiredAt}

mapper.select:
/* 정지 기간이 끝난 회원 번호 조회 : 영구 정지 제외 */
SELECT MBR_SN
  FROM MBR
 WHERE MBR_STTS_CD = #{suspendedSttsCd}
   AND SUSPN_END_DT <= #{expiredAt}

/* 정지 회원 목록 조회 : 정지 일시·사유·처리 관리자는 최근 정지 이력 */ SELECT M.MBR_SN , M.MBR_NCNM , H.REG_DT AS SUSPN_DT , M.SUSPN_END_DT , H.CHG_RSN AS SUSPN_RSN , P.MBR_NCNM AS PRCR_NCNM FROM MBR M LEFT JOIN MBR_STTS_HSTRY H ON H.MBR_STTS_HSTRY_SN = (SELECT MAX(S.MBR_STTS_HSTRY_SN) FROM MBR_STTS_HSTRY S WHERE S.MBR_SN = M.MBR_SN AND S.AFTR_STTS_CD = M.MBR_STTS_CD) LEFT JOIN MBR P ON P.MBR_SN = H.PRCS_MBR_SN WHERE M.MBR_STTS_CD = #{suspendedSttsCd}
AND M.MBR_NCNM LIKE CONCAT('%', #{mbrNcnm}, '%')
AND M.SUSPN_END_DT IS NULL
AND M.SUSPN_END_DT IS NOT NULL
ORDER BY H.REG_DT DESC , M.MBR_SN DESC

/* 정상 관리자 번호 잠금 조회 : 마지막 관리자 검사용 */
SELECT MBR_SN
  FROM MBR
 WHERE MBR_AUTHRT_CD = #{adminAuthrtCd}
   AND MBR_STTS_CD = #{normalSttsCd}
   FOR UPDATE

mapper.update:
/* 회원 권한 변경 */
UPDATE MBR
   SET MBR_AUTHRT_CD = #{afterAuthrtCd}
     , MDFR_ID = #{actorId}
     , MDFCN_DT = NOW()
 WHERE MBR_SN = #{mbrSn}
   AND MBR_AUTHRT_CD = #{beforeAuthrtCd}

   AND MBR_STTS_CD = #{mbrSttsCd}

mapper.select:
/* 상태별 회원 수 조회 */
SELECT COUNT(*)
  FROM MBR
 WHERE MBR_STTS_CD = #{mbrSttsCd}

/* 관리자 대시보드 최근 가입 회원 */
SELECT MBR_SN
     , MBR_NCNM
     , REG_DT
  FROM MBR
 WHERE MBR_AUTHRT_CD = #{mbrAuthrtCd}
   AND MBR_STTS_CD IN

    #{mbrSttsCd}

 ORDER BY REG_DT DESC
        , MBR_SN DESC
 LIMIT #{limit}
